<?php require_once '../config/config.php';$title='Recipes';$q=trim($_GET['q']??'');$c=$_GET['cuisine']??'';$d=$_GET['diet']??'';$df=$_GET['difficulty']??'';$sql="SELECT * FROM recipes WHERE status='approved'";$a=[];if($q){$sql.=" AND(title LIKE ? OR ingredients LIKE ? OR cuisine LIKE ?)";$x="%$q%";$a=[$x,$x,$x];}if($c){$sql.=" AND cuisine=?";$a[]=$c;}if($d){$sql.=" AND dietary_preference=?";$a[]=$d;}if($df){$sql.=" AND difficulty=?";$a[]=$df;}$sql.=" ORDER BY featured DESC,created_at DESC";$s=db()->prepare($sql);$s->execute($a);$recipes=$s->fetchAll();require '../includes/header.php';?><div class="page-hero"><div class="container"><span class="eyebrow">Discover</span><h1 class="fw-bold">Recipe Collection</h1><p class="lead">Recipes for every appetite and skill level.</p></div></div><section class="section"><div class="container"><form class="row g-2 mb-5"><div class="col-lg-4"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search recipes or ingredients"></div><div class="col-md-3 col-lg-2"><select class="form-select" name="cuisine"><option value="">Cuisine</option><?php foreach(['African','Asian','Italian','Mexican','Mediterranean'] as $x):?><option <?=$c===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="col-md-3 col-lg-2"><select class="form-select" name="diet"><option value="">Diet</option><?php foreach(['General','Vegetarian','Vegan','Gluten-Free','Dairy-Free','Low-Carb','High-Protein','Halal'] as $x):?><option <?=$d===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="col-md-3 col-lg-2"><select class="form-select" name="difficulty"><option value="">Difficulty</option><?php foreach(['Easy','Medium','Hard'] as $x):?><option <?=$df===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="col-md-3 col-lg-2"><button class="btn btn-primary w-100">Search</button></div></form><div class="row g-4"><?php foreach($recipes as $r):?><div class="col-md-6 col-lg-4"><div class="card recipe-card"><img src="<?=recipe_image($r['image'])?>" alt="<?=e($r['title'])?>"><div class="card-body"><span class="tag"><?=e($r['cuisine'])?></span><h5 class="mt-3"><?=e($r['title'])?></h5><p class="text-muted"><?=e(mb_strimwidth($r['description'],0,110,'...'))?></p><small><?=e($r['difficulty'])?> · <?=e((string)($r['prep_time']+$r['cook_time']))?> min</small><a href="recipe.php?id=<?=$r['id']?>" class="stretched-link"></a></div></div></div><?php endforeach;?></div></div></section><?php require '../includes/footer.php';?>